import { randomUUID } from "node:crypto";
import { tool } from "@langchain/core/tools";
import { z } from "zod";
import { logger } from "../../logger";

/**
 * Marker used by the chat UI ([ChatMessageBubble]) to detect a workforce
 * handoff card in this tool's output and render the card.
 * Keep this string in sync with the client-side parser.
 */
export const WORKFORCE_HANDOFF_MARKER = "WORKFORCE_HANDOFF_JSON";

export interface WorkforceHandoffPayload {
  // Stable identifier generated by the tool and embedded in the marker JSON.
  // Same value on live stream and chat reload because it's persisted inside
  // the tool's output content (the AI SDK's toolCallId differs across the
  // two paths, so we can't rely on that).
  handoff_id: string;
  title: string;
  rationale: string;
  instruction: string;
  agent_name: string;
}

export const proposeWorkforceHandoff = tool(
  async ({
    title,
    rationale,
    instruction,
    agent_name,
  }: {
    title: string;
    rationale: string;
    instruction: string;
    agent_name?: string;
  }) => {
    logger.debug(`🔧 TOOL CALLED: propose_workforce_handoff(title='${title}')`);

    const payload: WorkforceHandoffPayload = {
      handoff_id: randomUUID(),
      title: title.trim(),
      rationale: rationale.trim(),
      instruction: instruction.trim(),
      agent_name: agent_name?.trim() || "chat_handoff",
    };

    return [
      `Workforce handoff proposed: **${payload.title}**`,
      ``,
      payload.rationale,
      ``,
      `Instruction the Workforce will receive:`,
      `> ${payload.instruction}`,
      ``,
      `<!-- ${WORKFORCE_HANDOFF_MARKER}:${JSON.stringify(payload)} -->`,
    ].join("\n");
  },
  {
    name: "propose_workforce_handoff",
    description: `Propose handing a request off to the AI Workforce queue.

Use this tool for any request that modifies pipeline data — the Workforce is the only path for write actions. This includes:
  - L0→L1 promotions (single named company or batch).
  - Outbound search + screening + pipeline writes.
  - Adding companies, writing notes, sending emails.
  - Any multi-step job that touches pipeline state.

Do NOT use this tool for read-only analysis or single-tool answers — just answer directly.

Calling this tool does NOT enqueue anything itself. It renders a card in the chat that asks the user to confirm via "Assign to Workforce" or to keep the conversation in-chat via "Just answer here". After calling it, write a single short sentence explaining the offer and then STOP — do not start executing the plan yourself in the same turn.

Args:
    title: Short headline for the card (e.g. "Outbound search + L0/L1 screening + pipeline write").
    rationale: One sentence explaining why this is better suited to the Workforce.
    instruction: The exact instruction the Workforce will execute. Write it as a complete imperative sentence; the user will see it verbatim.
    agent_name: Optional agent identifier (defaults to "chat_handoff").`,
    schema: z.object({
      title: z.string().describe("Card headline"),
      rationale: z
        .string()
        .describe(
          "One-sentence rationale for why the Workforce is a better fit than answering in chat",
        ),
      instruction: z
        .string()
        .describe(
          "Exact instruction sent to the Workforce (imperative, complete sentence)",
        ),
      agent_name: z
        .string()
        .optional()
        .describe("Optional Workforce agent id (defaults to 'chat_handoff')"),
    }),
  },
);
